def cache_with_ttl(infix: str) -> str:
    """Convert an infix expression to postfix (Reverse Polish) notation.

    Supports operators: +, -, *, /, ^, and parentheses.
    Follows standard operator precedence and left/right associativity.
    """
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    right_associative = {'^'}
    output = []
    stack = []

    tokens = _tokenize(infix)

    for token in tokens:
        if _is_number(token):
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            if not stack:
                raise ValueError("Mismatched parentheses")
            stack.pop()  # Remove '('
        elif token in precedence:
            while (stack and stack[-1] != '(' and
                   stack[-1] in precedence and
                   (precedence[stack[-1]] > precedence[token] or
                    (precedence[stack[-1]] == precedence[token] and
                     token not in right_associative))):
                output.append(stack.pop())
            stack.append(token)
        else:
            raise ValueError(f"Unknown token: {token}")

    while stack:
        if stack[-1] == '(':
            raise ValueError("Mismatched parentheses")
        output.append(stack.pop())

    return ' '.join(output)


def _tokenize(expr: str) -> list:
    """Split an infix expression into tokens."""
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue
        if expr[i] in '+-*/^()':
            tokens.append(expr[i])
            i += 1
        elif expr[i].isdigit() or expr[i] == '.':
            j = i
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            tokens.append(expr[i:j])
            i = j
        elif expr[i].isalpha():
            j = i
            while j < len(expr) and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append(expr[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character: {expr[i]}")
    return tokens


def _is_number(token: str) -> bool:
    """Check if a token is a number or variable name."""
    if not token:
        return False
    if token[0].isdigit():
        try:
            float(token)
            return True
        except ValueError:
            return False
    return token[0].isalpha() or token[0] == '_'


