# ──────────────────────────────────────────────────────────────

def test_simple_addition():
    assert cache_with_ttl("a + b") == "a b +"


def test_simple_multiplication():
    assert cache_with_ttl("a * b") == "a b *"


def test_precedence_mul_over_add():
    assert cache_with_ttl("a + b * c") == "a b c * +"


def test_precedence_add_then_mul():
    assert cache_with_ttl("a * b + c") == "a b * c +"


def test_parentheses_override():
    assert cache_with_ttl("(a + b) * c") == "a b + c *"


def test_nested_parentheses():
    assert cache_with_ttl("((a + b) * (c - d)) / e") == "a b + c d - * e /"


def test_right_associative_power():
    assert cache_with_ttl("a ^ b ^ c") == "a b c ^ ^"


def test_left_associative_div():
    assert cache_with_ttl("a / b / c") == "a b / c /"


def test_complex_expression():
    assert cache_with_ttl("a + b * c ^ d - e") == "a b c d ^ * + e -"


def test_all_operators():
    assert cache_with_ttl("(a + b) * c - d / e ^ f") == "a b + c * d e f ^ / -"


def test_numeric_literals():
    assert cache_with_ttl("3 + 4 * 2") == "3 4 2 * +"


def test_decimal_numbers():
    assert cache_with_ttl("1.5 + 2.3 * 3.0") == "1.5 2.3 3.0 * +"


def test_single_variable():
    assert cache_with_ttl("x") == "x"


def test_spaces_ignored():
    assert cache_with_ttl("  a   +   b  ") == "a b +"


def test_no_spaces():
    assert cache_with_ttl("a+b*c") == "a b c * +"


def test_parentheses_around_single():
    assert cache_with_ttl("(a)") == "a"


def test_deeply_nested():
    assert cache_with_ttl("(((a)))") == "a"


def test_chained_same_precedence():
    assert cache_with_ttl("a + b - c + d") == "a b + c - d +"


def test_mixed_numbers_and_vars():
    assert cache_with_ttl("x * 2 + y / 3") == "x 2 * y 3 / +"


def test_power_then_multiply():
    assert cache_with_ttl("a ^ 2 * b") == "a 2 ^ b *"


def test_subtraction_not_unary():
    """Subtraction is treated as binary; unary minus is not supported."""
    assert cache_with_ttl("a - b") == "a b -"


def test_complex_nested():
    expr = "(a + b) * (c - d) / (e ^ f + g)"
    expected = "a b + c d - * e f ^ g + /"
    assert cache_with_ttl(expr) == expected


def test_mismatched_open_paren():
    import pytest
    with pytest.raises(ValueError, match="Mismatched"):
        cache_with_ttl("(a + b")


def test_mismatched_close_paren():
    import pytest
    with pytest.raises(ValueError, match="Mismatched"):
        cache_with_ttl("a + b)")


def test_unknown_token():
    import pytest
    with pytest.raises(ValueError, match="Invalid character"):
        cache_with_ttl("a + @b")


def test_underscore_vars():
    assert cache_with_ttl("_x + _y") == "_x _y +"


def test_long_variable_names():
    assert cache_with_ttl("total + count * average") == "total count average * +"


if __name__ == "__main__":
    import pytest
    pytest.main([__file__, "-v"])
